import struct

import pytest

from chassis_comm.protocol import (
    AimState, AimTarget, Command, FRAME_SIZE, FRAME_SIZES, FrameParser,
    NavigationTarget, crc16_modbus, decode_frame, encode_frame,
)


# Independent, verbatim vectors from minipc_protocol.md (not generated by the codec).
VECTORS = [
    (AimTarget(1, 1, 30, 15, 3.5),
     'A1 01 01 00 00 F0 41 00 00 70 41 00 00 60 40 04 D8'),
    (AimState(0, 25, .5, -.25, .75, .875),
     'A2 00 00 00 C8 41 00 00 00 3F 00 00 80 BE 00 00 40 3F 00 00 60 3F D5 DF'),
    (Command(1, 0, struct.unpack('<f', bytes.fromhex('DB 0F C9 3F'))[0]),
     'A3 00 00 00 80 3F 00 00 00 00 DB 0F C9 3F 00 00 00 00 00 00 00 00 5D EB'),
    (NavigationTarget(struct.unpack('<f', bytes.fromhex('DB 0F 49 3F'))[0], 1.5, -2.5),
     'A4 DB 0F 49 3F 00 00 C0 3F 00 00 20 C0 41 20'),
]


def test_modbus_standard_vector():
    assert crc16_modbus(b'123456789') == 0x4B37
    assert crc16_modbus(b'') == 0xFFFF


@pytest.mark.parametrize('message,hex_frame', VECTORS)
def test_protocol_reference_vectors(message, hex_frame):
    frame = bytes.fromhex(hex_frame)
    assert encode_frame(message) == frame
    assert decode_frame(frame) == message
    assert len(frame) == FRAME_SIZES[frame[0]]
    assert struct.unpack('<H', frame[-2:])[0] == crc16_modbus(frame[:-2])
    assert crc16_modbus(frame[:-2]) != crc16_modbus(frame[1:-2])


def test_navigation_offsets_and_nonzero_pose():
    message = Command(1, -2, .5, 1, 1.5, -2.5)
    frame = encode_frame(message)
    assert len(frame) == FRAME_SIZE == 24
    assert frame[:2] == b'\xa3\x01'
    for offset, value in zip((2, 6, 10, 14, 18), (1, -2, .5, 1.5, -2.5)):
        assert frame[offset:offset + 4] == struct.pack('<f', value)
    assert decode_frame(frame) == message


@pytest.mark.parametrize('field', ['vx', 'vy', 'yaw', 'x', 'y'])
@pytest.mark.parametrize('value', [float('nan'), float('inf'), -float('inf'), 1e100])
def test_unrepresentable_navigation_float_is_rejected(field, value):
    values = dict(vx=0, vy=0, yaw=0, x=0, y=0)
    values[field] = value
    with pytest.raises(ValueError):
        encode_frame(Command(**values))


@pytest.mark.parametrize('flag', [-1, 2, 255, 256])
def test_undefined_flags_are_rejected(flag):
    for message in (Command(0, 0, 0, flag), AimTarget(flag, 0, 0, 0, 0),
                    AimTarget(1, flag, 0, 0, 0), AimState(flag, 25, 0, 0, 0, 1)):
        with pytest.raises(ValueError):
            encode_frame(message)
    with pytest.raises(ValueError):
        encode_frame(AimTarget(0, 1, 0, 0, 0))


@pytest.mark.parametrize('message,hex_frame', VECTORS)
def test_each_single_bit_error_and_bad_length_are_rejected(message, hex_frame):
    frame = bytes.fromhex(hex_frame)
    for offset in range(len(frame)):
        for bit in range(8):
            damaged = bytearray(frame)
            damaged[offset] ^= 1 << bit
            with pytest.raises(ValueError):
                decode_frame(damaged)
    for invalid in (frame[:-1], frame + b'\x00', b'', b'\xaa\x55' + frame[2:]):
        with pytest.raises(ValueError):
            decode_frame(invalid)


def test_crc_valid_invalid_payload_is_rejected():
    for data in (b'\xa3' + struct.pack('<Bfffff', 2, 0, 0, 0, 0, 0),
                 b'\xa4' + struct.pack('<fff', float('nan'), 0, 0),
                 b'\xa2' + struct.pack('<Bfffff', 0, 25, 0, float('inf'), 0, 1)):
        with pytest.raises(ValueError):
            decode_frame(data + struct.pack('<H', crc16_modbus(data)))


@pytest.mark.parametrize('chunk_size', range(1, 31))
def test_mixed_stream_resync_after_noise_drop_and_bad_crc(chunk_size):
    frames = [bytes.fromhex(vector) for _, vector in VECTORS]
    bad = bytearray(frames[1])
    bad[-1] ^= 0x40
    stream = (b'noise\xaa\x55' + frames[2][:8] + bytes(bad)
              + frames[0] + frames[1] + frames[2] + frames[3] + b'end')
    parser = FrameParser()
    received = []
    for offset in range(0, len(stream), chunk_size):
        received.extend(parser.feed(stream[offset:offset + chunk_size]))
    assert received == [message for message, _ in VECTORS]
    assert len(parser._buffer) < max(FRAME_SIZES.values())


def test_direction_filter_consumes_complete_frames_and_resets_partial_input():
    parser = FrameParser(headers=(0xA2, 0xA4))
    frames = b''.join(bytes.fromhex(vector) for _, vector in VECTORS)
    assert parser.feed(frames) == [VECTORS[1][0], VECTORS[3][0]]
    target = bytes.fromhex(VECTORS[3][1])
    assert parser.feed(target[:5]) == []
    parser.reset()
    assert parser.feed(target[5:]) == []
    # Once enough bytes arrive, scanning recovers the next complete target.
    assert parser.feed(target + b'\x00' * 24) == [VECTORS[3][0]]
    parser.reset()
    assert parser.feed(target[:1]) == []
    assert parser.feed(target[1:]) == [VECTORS[3][0]]


def test_payload_containing_all_header_bytes_and_large_noise():
    value = struct.unpack('<f', bytes.fromhex('a1 a2 a3 a4'))[0]
    message = NavigationTarget(value, value, value)
    parser = FrameParser()
    assert parser.feed(b'\xff' * 100000 + encode_frame(message)) == [message]
    assert parser._buffer == b''


def test_a4_offsets_and_old_11_byte_frame_rejected():
    frame = bytes.fromhex(VECTORS[3][1])
    assert len(frame) == FRAME_SIZES[0xA4] == 15
    assert struct.unpack('<fff', frame[1:13]) == pytest.approx((.7853981634, 1.5, -2.5))
    assert struct.unpack('<H', frame[13:15])[0] == crc16_modbus(frame[:13])
    with pytest.raises(ValueError):
        decode_frame(bytes.fromhex('A4 00 00 C0 3F 00 00 20 C0 DC A2'))
